package webx

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"net/http"
	"strings"
)

// SessionHeader carries the window owner token. Every asset and every path
// grant in tmpstore is bound to this token (AGENTS §5.11), so a second window
// or another local process cannot read or overwrite the first one's assets.
//
// The token is generated by the front-end (crypto.getRandomValues) and echoed
// back on every /api request; there is no cookie, no login and no server-side
// session list. Possession of the token is the capability: 128 bits, so it is
// not guessable, and the Host/Origin guard (internal/app/middleware.go) keeps a
// foreign page from sending it.
const SessionHeader = "X-AutoStamp-Session"

// ErrSession is the shape every handler maps to a 400 bad_session.
var ErrSession = errors.New("缺少或不合法的会话令牌")

// SessionOf returns the owner token from the request, validating the format.
//
// A missing or malformed token is a client bug, not a security decision: the
// response is 400 so the front-end's error path shows it in the console and
// the tools/verify scripts fail loudly instead of silently sharing assets.
func SessionOf(r *http.Request) (string, error) {
	tok := strings.TrimSpace(r.Header.Get(SessionHeader))
	if tok == "" {
		return "", ErrSession
	}
	if len(tok) != 32 {
		return "", ErrSession
	}
	for _, c := range tok {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return "", ErrSession
		}
	}
	return tok, nil
}

// NewToken mints a token for server-side use (tests and the native picker do
// not carry a browser session). 16 random bytes, hex encoded: the same length
// the front-end generates, so SessionOf validates identically.
func NewToken() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return hex.EncodeToString(b[:]), nil
}
